import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"命令与权限","description":"","frontmatter":{},"headers":[],"relativePath":"modules/level/commands.md","filePath":"modules/level/commands.md","lastUpdated":0}`),a={name:`modules/level/commands.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="命令与权限" tabindex="-1">命令与权限 <a class="header-anchor" href="#命令与权限" aria-label="Permalink to “命令与权限”">​</a></h1><p>EmakiLevel 的主命令是 <code>/emakilevel</code>，别名为 <code>/elv</code> 和 <code>/elevel</code>。文档示例统一使用最短别名 <code>/elv</code>。</p><p>所有子命令都会先检查 <code>emakilevel.use</code>。也就是说，即使是管理员命令，执行者也必须同时拥有 <code>emakilevel.use</code> 和对应的管理权限。</p><h2 id="玩家命令" tabindex="-1">玩家命令 <a class="header-anchor" href="#玩家命令" aria-label="Permalink to “玩家命令”">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td><code>/elv</code></td><td><code>emakilevel.use</code></td><td>查看自己所有已加载等级类型的当前等级、经验、需求经验和进度。只能由玩家执行。</td></tr><tr><td><code>/elv info [type]</code></td><td><code>emakilevel.use</code></td><td>查看自己指定等级类型；不填 <code>type</code> 时等同 <code>/elv</code>。</td></tr><tr><td><code>/elv gui [type]</code></td><td><code>emakilevel.use</code></td><td>打开等级 GUI；不填 <code>type</code> 时使用 <code>config.yml &gt; primary_type</code>。别名：<code>/elv open [type]</code>。</td></tr><tr><td><code>/elv levelup [type]</code></td><td><code>emakilevel.levelup</code></td><td>手动升级指定等级类型；不填 <code>type</code> 时使用 <code>config.yml &gt; primary_type</code>，默认 <code>main</code>。别名：<code>/elv up [type]</code>。</td></tr><tr><td><code>/elv top [type]</code></td><td><code>emakilevel.top</code></td><td>查看指定等级类型的当前缓存排行榜前 10；不填 <code>type</code> 时使用主等级类型。</td></tr><tr><td><code>/elv topgui [type]</code></td><td><code>emakilevel.top</code></td><td>打开排行榜 GUI；不填 <code>type</code> 时使用主等级类型。别名：<code>/elv topopen [type]</code>。只能由玩家执行。</td></tr></tbody></table><p>示例：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/elv</span></span>
<span class="line"><span>/elv info combat</span></span>
<span class="line"><span>/elv gui main</span></span>
<span class="line"><span>/elv levelup mining</span></span>
<span class="line"><span>/elv up main</span></span>
<span class="line"><span>/elv top combat</span></span>
<span class="line"><span>/elv topgui combat</span></span></code></pre></div><p>手动升级会受到 <code>types/&lt;type&gt;.yml</code> 中以下字段影响：</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">upgrade</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">          # false 时完全禁止升级</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  manual_upgrade</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">   # false 时禁止 /elv levelup</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  cost</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">       # true 时需要满足经济/材料消耗</span></span></code></pre></div><p>如果某个类型只想通过获得经验自动升级，可以保留 <code>auto_upgrade: true</code>，并把 <code>manual_upgrade: false</code>。</p><h2 id="管理命令" tabindex="-1">管理命令 <a class="header-anchor" href="#管理命令" aria-label="Permalink to “管理命令”">​</a></h2><p>这些命令要求 <code>emakilevel.admin</code>，并且目标玩家必须在线，因为命令实现使用在线玩家名精确匹配。</p><table tabindex="0"><thead><tr><th>命令</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td><code>/elv giveexp &lt;player&gt; &lt;type&gt; &lt;amount&gt;</code></td><td><code>emakilevel.admin</code></td><td>给在线玩家增加经验。别名：<code>addexp</code>。会按该类型配置触发自动升级。</td></tr><tr><td><code>/elv takeexp &lt;player&gt; &lt;type&gt; &lt;amount&gt;</code></td><td><code>emakilevel.admin</code></td><td>扣除在线玩家当前等级内经验，最低为 0，不会自动降级。别名：<code>removeexp</code>。</td></tr><tr><td><code>/elv setexp &lt;player&gt; &lt;type&gt; &lt;amount&gt;</code></td><td><code>emakilevel.admin</code></td><td>设置在线玩家当前等级内经验，不直接改变等级。</td></tr><tr><td><code>/elv addlevel &lt;player&gt; &lt;type&gt; &lt;amount&gt;</code></td><td><code>emakilevel.admin</code></td><td>增加等级，结果会被限制在该类型 <code>start_level</code> 与 <code>max_level</code> 之间。别名：<code>givelevel</code>。</td></tr><tr><td><code>/elv takelevel &lt;player&gt; &lt;type&gt; &lt;amount&gt;</code></td><td><code>emakilevel.admin</code></td><td>扣除等级，结果不会低于 <code>start_level</code>。别名：<code>removelevel</code>。</td></tr><tr><td><code>/elv setlevel &lt;player&gt; &lt;type&gt; &lt;level&gt;</code></td><td><code>emakilevel.admin</code></td><td>设置等级，结果会被限制在该类型等级范围内。</td></tr><tr><td><code>/elv reset &lt;player&gt; &lt;type&gt;</code></td><td><code>emakilevel.admin</code></td><td>重置指定类型：等级回到 <code>start_level</code>，<code>exp</code> 与 <code>total_exp</code> 清零。</td></tr></tbody></table><p>示例：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/elv giveexp Steve combat 250</span></span>
<span class="line"><span>/elv takeexp Steve mining 30</span></span>
<span class="line"><span>/elv setexp Steve main 0</span></span>
<span class="line"><span>/elv addlevel Steve main 5</span></span>
<span class="line"><span>/elv takelevel Steve combat 1</span></span>
<span class="line"><span>/elv setlevel Steve fishing 20</span></span>
<span class="line"><span>/elv reset Steve mining</span></span></code></pre></div><p>经验与等级操作的差异：</p><table tabindex="0"><thead><tr><th>操作</th><th>改变等级</th><th>改变当前经验</th><th>改变总经验</th><th>备注</th></tr></thead><tbody><tr><td><code>giveexp</code></td><td>可能自动升级</td><td>增加并在升级时扣除需求经验</td><td>增加</td><td>自动升级取决于类型配置。</td></tr><tr><td><code>takeexp</code></td><td>否</td><td>扣除到最低 0</td><td>不变</td><td>不会降级。</td></tr><tr><td><code>setexp</code></td><td>否</td><td>设置为指定值</td><td>不变</td><td>适合修正当前等级内经验。</td></tr><tr><td><code>addlevel</code></td><td>是</td><td>清零</td><td>不变</td><td>直接改等级，不发放升级奖励。</td></tr><tr><td><code>takelevel</code></td><td>是</td><td>清零</td><td>不变</td><td>直接改等级，不回退奖励。</td></tr><tr><td><code>setlevel</code></td><td>是</td><td>清零</td><td>不变</td><td>用于管理员修正。</td></tr><tr><td><code>reset</code></td><td>是</td><td>清零</td><td>清零</td><td>回到该类型起始状态。</td></tr></tbody></table><h2 id="重载与调试命令" tabindex="-1">重载与调试命令 <a class="header-anchor" href="#重载与调试命令" aria-label="Permalink to “重载与调试命令”">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td><code>/elv reload</code></td><td><code>emakilevel.reload</code> 或 <code>emakilevel.admin</code></td><td>保存当前缓存数据，重载主配置、等级类型、需求、来源规则、语言、PDC 和属性桥接，并同步在线玩家。</td></tr><tr><td><code>/elv convert-legacy [confirm]</code></td><td><code>emakilevel.admin</code></td><td>把 <code>sources/*.yml</code> 中 <code>sources.&lt;id&gt;.rules[]</code> 的旧 <code>result_item_sources</code> 键转换为 <code>matcher</code> 块。不带参数只做预演；<code>confirm</code>（或 <code>--apply</code>）才实际改写，并留 <code>.bak</code> 备份。</td></tr><tr><td><code>/elv debug requirement &lt;type&gt; &lt;level&gt;</code></td><td><code>emakilevel.debug</code> 或 <code>emakilevel.admin</code></td><td>查看某个类型升到目标等级时的需求经验，以及命中的需求来源。</td></tr><tr><td><code>/elv debug pdc &lt;player&gt;</code></td><td><code>emakilevel.debug</code> 或 <code>emakilevel.admin</code></td><td>触发在线玩家 PDC 重新同步。实现上会同步所有在线玩家。</td></tr><tr><td><code>/elv debug</code></td><td><code>emakilevel.debug</code> 或 <code>emakilevel.admin</code></td><td>输出 CoreLib 调试状态概览。</td></tr><tr><td><code>/elv debug status</code> / <code>on</code> / <code>off</code></td><td><code>emakilevel.debug</code> 或 <code>emakilevel.admin</code></td><td>CoreLib 通用调试开关：查看状态、全部开启、全部关闭。</td></tr><tr><td><code>/elv debug player &lt;player&gt;</code></td><td><code>emakilevel.debug</code> 或 <code>emakilevel.admin</code></td><td>切换某个在线玩家的调试输出。</td></tr><tr><td><code>/elv debug module &lt;module&gt;</code></td><td><code>emakilevel.debug</code> 或 <code>emakilevel.admin</code></td><td>切换调试子模块。EmakiLevel 自身提供 <code>common</code>，另外可用 CoreLib 共享子模块 <code>action</code>、<code>item_operation</code>、<code>variables</code>、<code>placeholder</code>、<code>gui</code>。</td></tr></tbody></table><p>示例：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/elv reload</span></span>
<span class="line"><span>/elv debug requirement main 10</span></span>
<span class="line"><span>/elv debug requirement combat 35</span></span>
<span class="line"><span>/elv debug pdc Steve</span></span>
<span class="line"><span>/elv debug module common</span></span></code></pre></div><p><code>debug requirement</code> 的来源可能是：</p><table tabindex="0"><thead><tr><th>输出来源</th><th>含义</th></tr></thead><tbody><tr><td><code>type.values</code></td><td><code>types/&lt;type&gt;.yml &gt; requirement.values</code> 中写了目标等级的精确值。</td></tr><tr><td><code>type.formula</code></td><td><code>types/&lt;type&gt;.yml &gt; requirement.formula</code> 覆盖了分组/全局公式。</td></tr><tr><td><code>groups.&lt;group&gt;.values</code></td><td><code>requirements.yml &gt; groups.&lt;group&gt;.values</code> 中写了目标等级的精确值。</td></tr><tr><td><code>groups.&lt;group&gt;.formula</code></td><td>使用了 <code>requirements.yml &gt; groups.&lt;group&gt;.formula</code>。</td></tr><tr><td><code>global.values</code></td><td>使用了 <code>requirements.yml &gt; global.values</code>。</td></tr><tr><td><code>global.formula</code></td><td>使用了 <code>requirements.yml &gt; global.formula</code>。</td></tr></tbody></table><h2 id="权限节点" tabindex="-1">权限节点 <a class="header-anchor" href="#权限节点" aria-label="Permalink to “权限节点”">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>默认</th><th>覆盖范围</th></tr></thead><tbody><tr><td><code>emakilevel.use</code></td><td><code>true</code></td><td>使用主命令和基础查询命令，也是主命令自身的注册权限。所有子命令都会先检查此权限。</td></tr><tr><td><code>emakilevel.levelup</code></td><td><code>true</code></td><td>使用 <code>/elv levelup</code> / <code>/elv up</code>。</td></tr><tr><td><code>emakilevel.top</code></td><td><code>true</code></td><td>使用 <code>/elv top</code> 与 <code>/elv topgui</code> / <code>/elv topopen</code>。</td></tr><tr><td><code>emakilevel.reload</code></td><td><code>op</code></td><td>使用 <code>/elv reload</code>。</td></tr><tr><td><code>emakilevel.debug</code></td><td><code>op</code></td><td>使用 <code>/elv debug requirement</code> 与 <code>/elv debug pdc</code>。</td></tr><tr><td><code>emakilevel.admin</code></td><td><code>op</code></td><td>使用经验/等级管理命令，并可代替 reload/debug 的专用权限。</td></tr></tbody></table><p>常见 LuckPerms 示例：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/lp group default permission set emakilevel.use true</span></span>
<span class="line"><span>/lp group default permission set emakilevel.levelup true</span></span>
<span class="line"><span>/lp group default permission set emakilevel.top true</span></span>
<span class="line"><span>/lp group admin permission set emakilevel.admin true</span></span>
<span class="line"><span>/lp group admin permission set emakilevel.reload true</span></span>
<span class="line"><span>/lp group admin permission set emakilevel.debug true</span></span></code></pre></div><h2 id="常见失败原因" tabindex="-1">常见失败原因 <a class="header-anchor" href="#常见失败原因" aria-label="Permalink to “常见失败原因”">​</a></h2><p>命令和 API 返回的失败原因是固定英文 ID，语言文件会把常用原因翻译成玩家可读文本。</p><table tabindex="0"><thead><tr><th>原因 ID</th><th>常见场景</th></tr></thead><tbody><tr><td><code>player_not_found</code></td><td>目标玩家不存在、离线，或 API 调用没有有效 UUID。</td></tr><tr><td><code>player_data_unavailable</code></td><td>玩家等级数据尚未加载或已卸载。</td></tr><tr><td><code>type_not_found</code></td><td><code>type</code> 不存在，或者 <code>sources/*.yml</code> / Action 中写错类型 ID。</td></tr><tr><td><code>type_disabled</code></td><td>等级类型存在但 <code>enabled: false</code>。</td></tr><tr><td><code>invalid_amount</code></td><td>经验或等级数量小于等于 0，或设置经验时传入负数。</td></tr><tr><td><code>daily_cap_reached</code></td><td>该类型当日经验额度已用尽，见 <code>config.yml &gt; daily_caps</code>。</td></tr><tr><td><code>upgrade_disabled</code></td><td><code>upgrade.enabled: false</code>。</td></tr><tr><td><code>manual_upgrade_disabled</code></td><td>玩家手动执行 <code>/elv levelup</code>，但类型禁用了手动升级。</td></tr><tr><td><code>max_level</code></td><td>已达到该类型 <code>max_level</code>。</td></tr><tr><td><code>not_enough_exp</code></td><td>当前等级内经验不足以升到下一级。</td></tr><tr><td><code>not_enough_money</code></td><td>升级经济消耗不足。</td></tr><tr><td><code>not_enough_material</code></td><td>升级材料消耗不足。</td></tr><tr><td><code>cost_compensation_failed</code></td><td>升级消耗已扣除但后续步骤失败，且退还消耗时出错。</td></tr><tr><td><code>invalid_requirement</code></td><td>需求经验公式或配置结果小于等于 0，无法升级。</td></tr></tbody></table><p>通过公开 API 异步写入时还可能返回以下原因：<code>api_unavailable</code>、<code>not_entity_owner</code>、<code>player_offline</code>、<code>owner_schedule_retired</code>、<code>owner_schedule_rejected</code>。这些原因与线程归属调度有关，不由配置引起。</p>`,31)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};